-- Source-linked editorial expansion across all five disciplines.
-- URLs and source references verified against cited Quran and Hadith editions.
-- Publication means visible with editorial_draft status; independent scholar/clinical review remains pending.
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES('quran-commerce-ethics','quran-commerce-ethics','Trade and Fair Dealing in the Qur’an','التجارة والعدل في القرآن','Mutual consent, accurate measures and accountable agreements','quranic_themes','concept','Qur’anic passages approach trade through lawful consent, protection from unjust appropriation, accurate weights and clear treatment of time-bound debts. These are ethical starting points; they do not substitute for a complete school-specific commercial ruling.','Reference-led original editorial overview','business ethics Quran, trade in Quran, Quran business honesty, commerce, fairness, economic justice, mutual consent','Source citations checked; specialist interpretation review pending','editorial_draft','published','80');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('quran-commerce-ethics-s1','quran-commerce-ethics','The central ethical question','overview','A discussion of trade in the Qur’an should not be reduced to an isolated verse or a marketing slogan. The relevant texts address voluntary exchange, the rights of other people, contractual accountability, and conduct that becomes unjust even when it seems profitable.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('quran-commerce-ethics-s2','quran-commerce-ethics','Mutual consent and property rights','scripture','Qur’an 4:29 warns against consuming one another’s wealth wrongfully and makes an exception for trade carried out by mutual consent. This establishes an important ethical direction, but judging a specific contract requires its full terms and qualified scholarly interpretation.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('quran-commerce-ethics-s3','quran-commerce-ethics','Measures and honest delivery','scripture','Qur’an 83:1–3 condemns those who insist on receiving full measure while shortchanging others. The passage is especially relevant to quantity, representation and fairness in transactions; modern applications are interpretive extensions, not quotations from the verse.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('quran-commerce-ethics-s4','quran-commerce-ethics','Documentation and avoiding disputes','interpretation','Qur’an 2:282 discusses recording deferred debt and ensuring a just record. Its detailed context matters. An encyclopedia can explain why documentation protects parties without presenting a general one-size-fits-all legal form.','4');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('quran-commerce-ethics-s5','quran-commerce-ethics','Reading across disciplines','methodology','These passages should be read alongside authenticated Prophetic reports on truthful trade and the work of qualified jurists. A source-linked ethical overview is not a fatwa, and it should not be used to certify an investment product or commercial scheme.','5');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,verification_status,sort_order) VALUES('quran-commerce-ethics-r1','quran-commerce-ethics','quran','Qur’an — Surah an-Nisa','4:29','https://quran.com/4/29','pending','1');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,verification_status,sort_order) VALUES('quran-commerce-ethics-r2','quran-commerce-ethics','quran','Qur’an — Surah al-Mutaffifin','83:1–3','https://quran.com/83/1-3','pending','2');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,verification_status,sort_order) VALUES('quran-commerce-ethics-r3','quran-commerce-ethics','quran','Qur’an — Surah al-Baqarah','2:282','https://quran.com/2/282','pending','3');
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES('truthful-trade-sunnah','truthful-trade-sunnah','Truthfulness in Buying and Selling','الصدق في البيع والشراء','What the transmitted reports say about disclosure and deception','sunnah','concept','Sahih al-Bukhari 2079 connects truthful disclosure by seller and buyer with blessing in their transaction. Sahih Muslim 102 preserves a report about concealing a defect in goods. These reports illuminate business ethics while requiring precise attribution and context.','Reference-led original editorial overview','hadith on business, honest merchant, seller buyer, truthfulness trade, disclosure, deceit, fraud in sunnah','Source citations checked; specialist interpretation review pending','editorial_draft','published','80');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('truthful-trade-sunnah-s1','truthful-trade-sunnah','A matter of conduct, not merely a deal','overview','Questions about honesty in business are answered in transmitted reports that address behaviour in real transactions: telling the truth, explaining defects and refusing deceptive presentation. Exact collection references matter more than an unattributed motivational quotation.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('truthful-trade-sunnah-s2','truthful-trade-sunnah','Disclosure in a transaction','transmission','In Sahih al-Bukhari 2079, the report from Hakim bin Hizam speaks of buyers and sellers being truthful and making relevant qualities and faults known. The report connects transparency with blessing and warns against concealment and falsehood.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('truthful-trade-sunnah-s3','truthful-trade-sunnah','The goods that appeared sound','transmission','Sahih Muslim 102 records a report in which the Prophet ﷺ examines food offered for sale, discovers moisture beneath the surface, and criticises the failure to make the condition visible to buyers. This is a transmitted episode, not a modern inspection code.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('truthful-trade-sunnah-s4','truthful-trade-sunnah','Practical understanding','practice','For a contemporary reader, these reports invite questions about accurate product descriptions, hidden defects, exaggerated claims and a fair chance for buyers to assess what they receive. Modern contracts and regulations still need to be considered separately.','4');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('truthful-trade-sunnah-s5','truthful-trade-sunnah','Authenticity and limitations','methodology','Both citations identify collections and report numbers so the original wording and context can be checked. A commercial or religious ruling on a disputed product or structure should not be issued solely from these brief explanations.','5');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,verification_status,sort_order) VALUES('truthful-trade-sunnah-r1','truthful-trade-sunnah','hadith','Sahih al-Bukhari — Sales and Trade','2079','https://sunnah.com/bukhari:2079','pending','1');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,verification_status,sort_order) VALUES('truthful-trade-sunnah-r2','truthful-trade-sunnah','hadith','Sahih Muslim — Book of Faith','102','https://sunnah.com/muslim:102','pending','2');
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES('prophetic-market-conduct','prophetic-market-conduct','Market Conduct in the Prophetic Era','أخلاق السوق في العهد النبوي','A sourced historical episode about fair presentation of goods','seerah','historical','A report in Sahih Muslim 102 describes the Prophet ﷺ encountering goods for sale with moisture hidden below their surface and criticising concealment. Studying the episode as Seerah means keeping its precise source, scene and interpretive limits visible.','Reference-led original editorial overview','market in seerah, prophet market, prophet business ethics, market trade Prophet, trade in prophetic era, historical marketplace','Source citations checked; specialist interpretation review pending','editorial_draft','published','80');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('prophetic-market-conduct-s1','prophetic-market-conduct','Historical window on the marketplace','historical','The Prophetic-era marketplace can be studied through reports that document specific encounters rather than imagined complete reconstructions. Individual accounts show actions and concerns, not necessarily a full picture of every trade custom of the period.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('prophetic-market-conduct-s2','prophetic-market-conduct','The food-display encounter','transmission','Sahih Muslim 102 reports that the Prophet ﷺ put his hand into a heap of food and found moisture. When the seller explained that rain had affected it, the Prophet questioned why the affected part had not been shown so people could see it.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('prophetic-market-conduct-s3','prophetic-market-conduct','The ethical significance','interpretation','A historically grounded lesson from this report is that appearances can mislead buyers when defects are concealed. This gives a concrete transmitted example of concern for fair dealing, but should not be overextended into claims about an entire regulated market system.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('prophetic-market-conduct-s4','prophetic-market-conduct','Related commercial reports','transmission','Sahih al-Bukhari 2079 transmits instruction about truthfulness and making a product’s qualities or defects known in sale. It is useful related material, distinct from the specific marketplace encounter in Sahih Muslim.','4');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('prophetic-market-conduct-s5','prophetic-market-conduct','Historical verification policy','methodology','The encyclopedia separates a directly traceable report from later biography, popular retelling and imaginative visual reconstruction. Dates, exact market locations and additional dialogue must not be invented when the cited narration does not supply them.','5');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,verification_status,sort_order) VALUES('prophetic-market-conduct-r1','prophetic-market-conduct','hadith','Sahih Muslim — Report of concealed moisture in goods','102','https://sunnah.com/muslim:102','pending','1');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,verification_status,sort_order) VALUES('prophetic-market-conduct-r2','prophetic-market-conduct','hadith','Sahih al-Bukhari — Truthful transactions','2079','https://sunnah.com/bukhari:2079','pending','2');
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES('traditional-remedies-safety','traditional-remedies-safety','Traditional Remedies and Modern Treatment Safety','سلامة العلاج والطب النبوي','How to evaluate claimed benefits without confusing tradition and clinical proof','prophetic_medicine','concept','Islamic texts contain healing-related passages and recorded traditional practices. They cannot by themselves establish the efficacy, dose, purity or safety of a present-day retail medicine. Religious context and medical evidence require separate review.','Reference-led original editorial overview','medicine safety, supplements, herbs, natural remedies, adverse effects, does prophetic medicine cure disease, medicine interaction, remedies and diabetes, medication','Source citations checked; specialist interpretation review pending','editorial_draft','published','80');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('traditional-remedies-safety-s1','traditional-remedies-safety','Three independent questions','overview','When an ingredient or practice is labelled Prophetic Medicine, examine three different questions: whether the religious attribution is authentic, what the historical description actually concerns, and whether the present-day intervention has credible evidence of benefit and acceptable risks for a specific condition.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('traditional-remedies-safety-s2','traditional-remedies-safety','A Qur’anic healing reference','scripture','Qur’an 16:69 describes a drink emerging from bees and mentions healing. The passage does not specify universal clinical indications, standardised medical doses or the safety of every marketed honey product.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('traditional-remedies-safety-s3','traditional-remedies-safety','Evidence is condition-specific','science','Research findings about an ingredient cannot be freely applied to every illness, formulation or retail product. A small study, an animal experiment, and a properly assessed clinical outcome support different levels of inference. Medical claims must state those limits.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('traditional-remedies-safety-s4','traditional-remedies-safety','Interactions and necessary treatment','safety','People taking prescription medicines, managing chronic illness, preparing for surgery, or caring for children should consult appropriate clinicians before using concentrated herbal products or supplements. Traditional ingredients should not replace insulin, emergency treatment or other indicated care. Unexpected reactions require medical attention.','4');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('traditional-remedies-safety-s5','traditional-remedies-safety','How the encyclopedia handles sellers','methodology','An independently verified ingredient seller may eventually be listed for product discovery. Seller verification is not clinical approval, scholarly certification or a recommendation to treat disease. The source record, safety warning and seller offer remain different kinds of content.','5');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,verification_status,sort_order) VALUES('traditional-remedies-safety-r1','traditional-remedies-safety','quran','Qur’an — Surah an-Nahl','16:69','https://quran.com/16/69','pending','1');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,verification_status,sort_order) VALUES('traditional-remedies-safety-r2','traditional-remedies-safety','clinical','US NIH NCCIH — Diabetes and Dietary Supplements','Evidence and safety review','https://www.nccih.nih.gov/health/diabetes-and-dietary-supplements-what-you-need-to-know','pending','2');
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES('islamic-business-ethics','islamic-business-ethics','Business Ethics in Islam','أخلاق الأعمال في الإسلام','A practical source-linked introduction to truthfulness, fair trade and accountability','living_guidance','guidance','Islamic commercial ethics include fair consent, truthful dealing, accurate representation and responsibility for obligations. The Qur’an and transmitted Hadith provide foundations; applied rulings depend on circumstances and specialist interpretation.','Reference-led original editorial overview','business ethics, islam business, ethical commerce, honesty at work, halal business conduct, trade ethics, business in islam','Source citations checked; specialist interpretation review pending','editorial_draft','published','80');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('islamic-business-ethics-s1','islamic-business-ethics','The short answer','overview','Islamic sources treat ethical business as more than making an exchange technically possible. The way parties communicate, describe goods, respect agreements and avoid taking advantage of one another matters. Honesty is not optional just because a deal appears profitable.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('islamic-business-ethics-s2','islamic-business-ethics','Trade by mutual consent','scripture','Qur’an 4:29 addresses unjust appropriation of property and trade conducted by mutual consent. This directs attention to willing participation and protection from wrongful gain, while leaving detailed modern contract classification to qualified analysis.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('islamic-business-ethics-s3','islamic-business-ethics','Transparent claims and real defects','transmission','Sahih al-Bukhari 2079 speaks of truthful buyers and sellers who make relevant qualities and defects clear. Sahih Muslim 102 records the Prophet ﷺ challenging concealed wetness in goods offered for sale. Both point to practical integrity.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('islamic-business-ethics-s4','islamic-business-ethics','Document obligations','practice','Qur’an 2:282 offers detailed instruction concerning the recording of deferred debts. For contemporary commerce, the wider ethical lesson includes clarity about payment terms and obligations, while exact religious and civil legal requirements must be assessed in context.','4');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('islamic-business-ethics-s5','islamic-business-ethics','What this does not decide','methodology','This introductory article does not rule on a specific financing structure, insurance contract, digital asset, franchise, commission arrangement or disputed sale. These questions may require documented facts, applicable law and a competent Islamic legal opinion.','5');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,verification_status,sort_order) VALUES('islamic-business-ethics-r1','islamic-business-ethics','quran','Qur’an — Surah an-Nisa','4:29','https://quran.com/4/29','pending','1');
